insert into public.cpl_memory (slug,kind,title,summary,tags,status,source,verified_by,verified_at,author,event_date) values
('d-stop-rule-fired-s681','decision','The stop rule fired on Chabot''s load: no new read, load or apply that night','S681 conductor, under the brief on #3358 ("Stop if a rollback undoes over 1% of a day''s rows"): Chabot''s rollback undid 1,013 of the UTC day''s 5,735 outline rows (17.7%). From 11:06Z no new read, load or apply; reviews finished on branches; repairs of the wrong load went ahead; Sam told at about 11:20Z. Default on no reply: the next night applies the two reviewed plans and reads Chabot again.',array['conductor','program-requirements-harvest','course-outcomes','stop-rule'],'proposed','#3506; #3509; docs/reference/conductor_mode.md','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('d-lane-names-only-colleges-in-flight-s681','decision','The collection lane names a college only while a run is in flight there','S681 conductor: Crafton Hills and College of the Siskiyous were named in the collection lane for two outcome preparation runs never started, and S680''s applied named-gaps plan holds a Siskiyous row a corrective write must reach. Both left the lane at 10:51Z, before any cheap-piles write. #3508 carries five colleges and RELEASED seven.',array['conductor','program-requirements-harvest','collection-lane'],'proposed','#3506; #3508; kb/collection_lane.py','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('d-named-gap-labels-corrected-s681','decision','Named-gap labels corrected before the 99-row plan','S681 conductor (#3497, COBIx''s four findings): an hours-measured program takes no_hours_read; ge_pattern is None with no degree total; a may-continue note caps course_list_match at 50 by an explicit list of three reviewed records (Fullerton 18166, Santa Ana 34014, Taft 31290), since the matcher had no self-recall; 33 records held out until read free; the strict sentence check stays.',array['program-requirements-harvest','named-gaps','cheap-piles'],'proposed','#3497; kb/receipts/program_requirement_records_named_gaps_2026-11-18_s681.json','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('d-a5-rows-confidence-56-s681','decision','The five A5 rows take unit arithmetic 56 and a note','S681 conductor (#3497 part C): Chaffey 38854, Marin 36465, Madera 44516, Merritt 33540 and Saddleback 40326 take unit arithmetic 56 with the note "Passed by units rule A5, right on 69 of 123 held answers in its self-check." and still pass. Reviewed, not applied (the stop rule).',array['program-requirements-harvest','units-rules','confidence'],'proposed','#3497','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('d-a4-pair-members-carry-state-units-s681','decision','A4: a paired group''s members carry the state course file''s units','S681 conductor (#3508): a member of a group whose members together replace the row carries the units in unified_courses_members.js when the file holds every member and they add to the row''s units or fall in its printed range; otherwise the group carries together_units and a note. A5_ON = False. The 13-row corrective write waits on two findings and the display readers.',array['program-requirements-harvest','units-rules','cheap-piles'],'proposed','#3508','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('d-census-order-s681','decision','Gap census order: passing, discontinued, named gap, then the piles','S681 conductor (#3497''s merge of main, kb/_harvest_gap_census.py): a passing record counts first, then a discontinued program leaves the gap, then a record with a named gap counts as collected, then main''s piles and named_gaps.',array['program-requirements-harvest','gap-census'],'proposed','#3497; kb/_harvest_gap_census.py','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('d-one-wave-chabot-out-s681','decision','Chabot left wave #3509 by a revert of its merge','S681 conductor: wave #3509 carries #3507 (display), #3499 (Lassen), #3284 (Allan Hancock) and #3494 (Santiago Canyon) in one merge of main, one CI and one squash. Chabot''s merge was reverted out (bf9703bb, git revert -m 1), since a wave lands as a squash; COBIx agreed at 11:11Z.',array['conductor','merging','wave'],'proposed','#3509','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('p-outcome-load-without-standing-test-s681','pitfall','An outline load ran past red objectives checks','S681: tests/course_outcomes_objectives_standing_test.py checks 8 and 9 were red on Chabot''s read branch, but a runner''s commit gets no CI and step 11 pushed .load when the slices filed complete, so 1,013 objectives loaded as SLOs. Run the standing test on the branch before pushing .load; no push while a check fails for that college. A plain session adds it to course-outcomes-load.yml.',array['course-outcomes','scheduled-sessions','rule-10'],'proposed','#3492; docs/reference/scheduled_sessions.md step 11','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('p-self-check-on-totals-misses-per-course-units-s681','pitfall','A self-check on totals cannot see per-course units','S681 (#3508): units rule A4 scored 74 of 74 on totals while copying a row''s units onto each member of a paired alternative (Coastline 18223: SPAN C180A to C185B at 5 units each, the state file 2.5). A self-check must compare the fields a rule writes against an independent source. KB note methodology-a-self-check-must-see-what-the-rule-writes.',array['program-requirements-harvest','units-rules','self-check'],'proposed','#3508; docs/kb-notes/methodology-a-self-check-must-see-what-the-rule-writes.md','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('p-superseded-ci-holds-the-migrate-queue-s681','pitfall','Superseded CI runs hold the migrate queue','S681: about a dozen pushes to PR branches in 45 minutes each started a full CI (six suites, lints, the size guard at 20 minutes or more) and queued the Chabot rollback''s supabase-migrate run for 11 minutes. Cancel CI on branches a wave carries, batch a worker''s pushes, and expect a migrate run to queue behind CI.',array['conductor','ci','runners'],'proposed','docs/reference/conductor_mode.md','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('m-display-build-through-bucket-s681','milestone','The first display build through the bucket path','S681 (#3507): build 545de21a6edc from main''s records; step=display run 44286209178 stored the receipt in cpl-receipts (18,109,323 bytes), filed its index entry and applied it: 18,209 planned, 18,209 written, 0 errors. The prior build was f0f1ee88c04f, not cdd185495ce4; both receipts are in the index, so the rollback is reachable.',array['program-requirements-harvest','repo-size','display'],'proposed','#3507; docs/reference/lanes/repo-size.md','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('m-outcome-loads-s681','milestone','Allan Hancock and Santiago Canyon outlines loaded','S681: Allan Hancock (#3284, load run 44285436479) 1,772 inserted, 5 skipped; Santiago Canyon (#3494, load run 44285667921) 498 inserted, 2,728 kept (Santa Ana''s blocks on host sac), 8 skipped. Net outline rows added: 2,270. Receipts kb/receipts/course_outcomes_hancockcollege_44285436479.json and course_outcomes_sac_44285667921.json.',array['course-outcomes','collection'],'proposed','#3284; #3494','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('m-chabot-load-rolled-back-s681','milestone','Chabot''s 1,013 mislabeled outline rows rolled back','S681: Chabot''s load (run 44285558570) filed every course''s objectives as SLOs (headings Measurable Objectives: and 3. Student Learning Outcomes unknown to the reader). The rollback (kb/migrations/2026-11-18_s681_course_outcomes_chabot_rollback.sql, ids 30392 to 31404, guarded to exactly 1,013) ran as migrate run 44292682081: deleted 1,013; live 0 Chabot rows, 30,321 in all. Reader fix on #3492.',array['course-outcomes','rule-10','rollback'],'proposed','#3492; #3509','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('f-lassen-five-records-s681','fact','Lassen''s five reread records: two pass, three collected with a named gap','S681 live read: reread run 44263840460 replaced 31132, 33263, 33729, 33730 and 42300 (ge_units 34). 33729 and 33730 pass; 31132 and 42300 count 58 of 60 and 33263 54 of 60, each with the gap "the record says electives fill the degree total, but the catalog text names no electives." 31297, 35106 and 41912 stay held (hold in kb/program_requirements_reconcile.json).',array['program-requirements-harvest','lassen'],'proposed','#3499','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18'),
('pr-read-live-handoff-from-open-pr-s681','procedure','Read a live session''s handoff from its open pull request','S681: a firing that finds a checkpoint PR updated in the last half hour reads that session''s handoff from the PR head (get_file_contents at refs/pull/N/head) and takes the queue the minute it merges, instead of ending in one line. S681 read handoff 681 from #3487 and started at 10:14Z when it merged.',array['scheduled-sessions','conductor','coordination'],'proposed','docs/reference/scheduled_sessions.md step 1','SkyGrebe (S681), the conductor',null,'SkyGrebe (S681)',date '2026-11-18')
insert into public.cpl_memory_log (memory_id, actor, action, note, after)
